// One bounded network operation, including response-body consumption. Preserve
// both the caller cancellation and any timeout/signal supplied by the SDK.
export function boundedFetch(fetcher: typeof fetch, parent?: AbortSignal, deadlineMs = 8000): typeof fetch {
  return (input, init) => {
    const signals: AbortSignal[] = [AbortSignal.timeout(deadlineMs)];
    if (parent) signals.push(parent);
    const initSignal = (init as { signal?: AbortSignal | null } | undefined)?.signal;
    if (initSignal) signals.push(initSignal);
    if (input instanceof Request) signals.push(input.signal);
    return fetcher(input, { ...init, signal: AbortSignal.any(signals) });
  };
}

type Caller = { rpc(name: string, args: Record<string, unknown>): PromiseLike<{ data: unknown; error: unknown }> };

// Invoke with the verified caller's Authorization header, never a service key.
// This reaches the authoritative Auth/session/member/device checks even when
// the protected handler subsequently uses a service client or external API.
export async function businessSessionAllowed(caller: Caller): Promise<boolean> {
  try { const {data,error}=await caller.rpc('business_session_allowed',{});return !error&&data===true; }
  catch { return false; }
}
export function guardBusinessRequest(
  handler: (request: Request) => Response | Promise<Response>,
  client: (request: Request) => Caller,
  shouldCheck: (request: Request) => boolean = request => request.method !== 'OPTIONS',
) {
  return async (request: Request): Promise<Response> => {
    if (shouldCheck(request) && !await businessSessionAllowed(client(request))) {
      return new Response(JSON.stringify({error:'Sign in again to continue.',code:'ACTIVE_SESSION_REQUIRED'}),{
        status:401,headers:{'Content-Type':'application/json','Cache-Control':'private, no-store, max-age=0',
          'CDN-Cache-Control':'no-store','Access-Control-Allow-Origin':'*','Access-Control-Allow-Headers':'authorization,apikey,x-client-info,content-type,range',
          'Access-Control-Allow-Methods':'POST,GET,HEAD,OPTIONS'},
      });
    }
    return handler(request);
  };
}

import { createClient } from 'npm:@supabase/supabase-js@2.112.3';
import { guardBusinessRequest } from './businessSessionGuard.ts';
import { boundedFetch } from './boundedFetch.ts';

export function serveBusinessRequest(handler: (request: Request) => Response | Promise<Response>, shouldCheck?: (request: Request) => boolean) {
  Deno.serve(guardBusinessRequest(handler, request => createClient(
    Deno.env.get('SUPABASE_URL')!,Deno.env.get('SUPABASE_ANON_KEY')!,{
      auth:{persistSession:false,autoRefreshToken:false},
      global:{headers:{Authorization:request.headers.get('Authorization')||''},fetch:boundedFetch(fetch,request.signal)},
    },
  ),shouldCheck));
}

import { plainHostname, PreviewError, type Address } from './networkPolicy.ts';
import type { FetchKind, PinnedResult } from './transport.ts';

type Connection = Pick<Deno.Conn, 'read' | 'write' | 'close'>;
type TlsConnection = Connection & { handshake(): Promise<unknown> };
type Connector = {
  connect(options: {hostname: string; port: number}): Promise<Connection>;
  startTls(connection: Connection, options: {hostname: string; alpnProtocols: string[]}): Promise<TlsConnection>;
};
const MAX_BYTES = {html: 300_000, image: 2_000_000};
const MAX_HEADERS = 16_384;
const encoder = new TextEncoder();
const redirects = new Set([301, 302, 303, 307, 308]);
const defaultConnector: Connector = {
  connect: options => Deno.connect(options),
  startTls: (connection, options) => Deno.startTls(connection as Deno.TcpConn, options),
};

// A single bounded buffer is shared by the HTTP head and body parsers. No
// response-controlled allocation occurs before its length has been checked.
class Reader {
  private buffer = new Uint8Array(16_384);
  private offset = 0;
  private available = 0;
  constructor(private connection: Connection) {}
  async some(maximum: number): Promise<Uint8Array | null> {
    if (this.offset === this.available) {
      const size = await this.connection.read(this.buffer);
      if (size === null) return null;
      if (size <= 0) throw new PreviewError('upstream');
      this.offset = 0; this.available = size;
    }
    const end = Math.min(this.available, this.offset + maximum);
    const bytes = this.buffer.slice(this.offset, end); this.offset = end;
    return bytes;
  }
  async line(maximum: number): Promise<string> {
    let result = '', carriage = false;
    for (;;) {
      const part = await this.some(1);
      if (!part) throw new PreviewError('upstream');
      const byte = part[0];
      if (carriage) {
        if (byte !== 10) throw new PreviewError('upstream');
        return result;
      }
      if (byte === 13) carriage = true;
      else {
        if (byte === 10 || result.length >= maximum) throw new PreviewError('upstream');
        result += String.fromCharCode(byte);
      }
    }
  }
}

async function readHead(reader: Reader) {
  let used = 0;
  const line = async () => {
    const value = await reader.line(MAX_HEADERS - used);
    used += value.length + 2;
    if (used > MAX_HEADERS) throw new PreviewError('upstream');
    return value;
  };
  // Informational responses are allowed, with one shared byte/count budget.
  for (let interim = 0; interim < 4; interim++) {
    const status = (await line()).match(/^HTTP\/1\.[01] ([1-5]\d\d)(?:[ \t][\x20-\x7e]*)?$/);
    if (!status) throw new PreviewError('upstream');
    const headers: Record<string, string> = Object.create(null);
    let count = 0;
    for (;;) {
      const value = await line(); if (!value) break;
      if (++count > 100) throw new PreviewError('upstream');
      const match = value.match(/^([!#$%&'*+.^_`|~0-9A-Za-z-]+):[ \t]*([\x09\x20-\x7e\x80-\xff]*)$/);
      if (!match) throw new PreviewError('upstream');
      const name = match[1].toLowerCase();
      if (['location', 'content-type', 'content-encoding', 'content-length', 'transfer-encoding'].includes(name)) {
        if (name in headers) throw new PreviewError('upstream');
        headers[name] = match[2].trim();
      }
    }
    const code = Number(status[1]);
    if (code >= 200) return {status: code, headers};
    if (code === 101 || headers['content-length'] || headers['transfer-encoding']) throw new PreviewError('upstream');
  }
  throw new PreviewError('upstream');
}

async function readBody(reader: Reader, headers: Record<string, string>, kind: FetchKind): Promise<Uint8Array> {
  const limit = MAX_BYTES[kind];
  const length = headers['content-length'], transfer = headers['transfer-encoding'];
  if (length !== undefined && (!/^\d+$/.test(length) || !Number.isSafeInteger(Number(length)))) throw new PreviewError('upstream');
  if (transfer !== undefined && (transfer.toLowerCase() !== 'chunked' || length !== undefined)) throw new PreviewError('upstream');
  if (kind === 'image' && length !== undefined && Number(length) > limit) throw new PreviewError('too_large');
  const chunks: Uint8Array[] = []; let size = 0;
  const add = (bytes: Uint8Array) => {
    if (kind === 'image' && size + bytes.length > limit) throw new PreviewError('too_large');
    const part = bytes.subarray(0, limit - size); chunks.push(part); size += part.length;
  };
  const exact = async (count: number) => {
    while (count > 0) {
      if (kind === 'html' && size >= limit) return false;
      const part = await reader.some(Math.min(count, limit - size + (kind === 'image' ? 1 : 0)));
      if (!part) throw new PreviewError('upstream');
      add(part); count -= part.length;
    }
    return true;
  };
  if (transfer !== undefined) {
    let framing = 0;
    for (;;) {
      const line = await reader.line(1024); framing += line.length + 2;
      // The decoded body AND its framing are bounded. Tiny chunks cannot force
      // unbounded parser work before the absolute network deadline fires.
      if (framing > 64_000 || !/^[0-9a-fA-F]{1,16}(?:;[\x20-\x7e]*)?$/.test(line)) throw new PreviewError('upstream');
      const count = Number.parseInt(line.split(';')[0], 16);
      if (!Number.isSafeInteger(count)) throw new PreviewError('upstream');
      if (count === 0) {
        let trailers = 0;
        for (;;) {
          const trailer = await reader.line(MAX_HEADERS - trailers);
          trailers += trailer.length + 2;
          if (trailers > MAX_HEADERS) throw new PreviewError('upstream');
          if (!trailer) break;
          if (!/^[!#$%&'*+.^_`|~0-9A-Za-z-]+:[\x09\x20-\x7e\x80-\xff]*$/.test(trailer)) throw new PreviewError('upstream');
          if (/^(content-length|transfer-encoding|content-type|content-encoding|location):/i.test(trailer)) throw new PreviewError('upstream');
        }
        break;
      }
      if (kind === 'image' && count > limit - size) throw new PreviewError('too_large');
      if (!await exact(count) || (kind === 'html' && size >= limit)) break;
      if (await reader.line(0) !== '') throw new PreviewError('upstream');
      framing += 2;
    }
  } else if (length !== undefined) {
    await exact(Number(length));
  } else {
    for (;;) {
      if (kind === 'html' && size >= limit) break;
      const part = await reader.some(limit - size + (kind === 'image' ? 1 : 0));
      if (!part) break;
      add(part);
    }
  }
  const output = new Uint8Array(size); let offset = 0;
  for (const part of chunks) {output.set(part, offset); offset += part.length;}
  return output;
}

// Deno 2.1's node:https shim ignores the separate TLS servername. Use its native
// TCP/TLS APIs so the socket destination stays pinned to the validated IP while
// certificate validation and SNI use the original hostname. No insecure retry.
export function createDenoPinnedRequest(connector: Connector = defaultConnector) {
  return async (url: URL, address: Address, kind: FetchKind, signal: AbortSignal): Promise<PinnedResult> => {
    let connection: Connection | undefined, closed = false;
    const close = () => {closed = true; try {connection?.close();} catch { /* already closed */ }};
    const check = () => {if (closed || signal.aborted) throw new PreviewError('timeout');};
    const retain = <T extends Connection>(value: T): T => {
      if (closed || signal.aborted) {try {value.close();} catch { /* already closed */ } throw new PreviewError('timeout');}
      connection = value; return value;
    };
    signal.addEventListener('abort', close, {once: true});
    try {
      check();
      await connector.connect({hostname: address.address, port: url.protocol === 'https:' ? 443 : 80}).then(retain);
      if (url.protocol === 'https:') {
        const tls = await connector.startTls(connection!, {hostname: plainHostname(url), alpnProtocols: ['http/1.1']}).then(retain);
        await tls.handshake(); check();
      }
      const request = encoder.encode(`GET ${url.pathname}${url.search} HTTP/1.1\r\nHost: ${url.host}\r\nAccept: text/html,application/xhtml+xml,image/avif,image/webp,image/png,image/jpeg,image/gif;q=0.8\r\nAccept-Encoding: identity\r\nConnection: close\r\nUser-Agent: PlatinumCirclesPreview/2.0 (+https://platinumcircles.app)\r\n\r\n`);
      for (let offset = 0; offset < request.length;) {
        check(); const written = await connection!.write(request.subarray(offset));
        if (written <= 0) throw new PreviewError('upstream'); offset += written;
      }
      const reader = new Reader(connection!), {status, headers} = await readHead(reader); check();
      if (redirects.has(status)) return {status, headers, bytes: new Uint8Array()};
      if (status !== 200 || (headers['content-encoding'] && headers['content-encoding'].toLowerCase() !== 'identity')) throw new PreviewError('upstream');
      const mime = (headers['content-type'] || '').split(';')[0].trim().toLowerCase();
      if (kind === 'html' ? !['text/html','application/xhtml+xml'].includes(mime) : !['image/jpeg','image/png','image/gif','image/webp','image/avif'].includes(mime)) throw new PreviewError('upstream');
      const bytes = await readBody(reader, headers, kind); check();
      return {status, headers, bytes};
    } catch (failure) {
      throw failure instanceof PreviewError ? failure : new PreviewError(signal.aborted ? 'timeout' : 'upstream');
    } finally {close(); signal.removeEventListener('abort', close);}
  };
}

import { plainHostname, previewUrl } from './networkPolicy.ts';
import { rasterMime, type FetchKind, type SafeResult } from './transport.ts';

export type PreviewRow = {
  url: string; title: string | null; description: string | null;
  image_url: string | null; domain: string | null; fetched_at: string;
  verified_at: string | null; image_origin_url: string | null; image_token: string;
};
type Dependencies = {
  base: string;
  authenticate: (authorization: string) => Promise<{id:string;anonymous?:boolean} | null>;
  read: (url: string) => Promise<PreviewRow | null>;
  save: (row: PreviewRow) => Promise<PreviewRow>;
  claim: (actor: string) => Promise<boolean>;
  image: (token: string) => Promise<string | null>;
  claimImage: (token: string) => Promise<boolean>;
  fetch: (url: string,kind: FetchKind,signal?: AbortSignal) => Promise<SafeResult>;
  now?: () => number;
  randomId?: () => string;
};
const ID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const CORS = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
  'Access-Control-Allow-Headers': 'authorization, apikey, content-type, x-client-info, x-supabase-client-platform, x-supabase-client-platform-version, x-supabase-client-runtime, x-supabase-client-runtime-version',
};
const PRIVATE = { ...CORS, 'Cache-Control': 'no-store', 'CDN-Cache-Control': 'no-store', 'X-Content-Type-Options': 'nosniff' };
const json = (value: unknown,status = 200) => new Response(JSON.stringify(value),{status,headers:{...PRIVATE,'Content-Type':'application/json'}});
const error = (status: number) => json({error: status === 401 ? 'Sign in to load a link preview.' : status === 429 ? 'Please wait a moment before loading another preview.' : 'This link preview is unavailable.'},status);
class PreviewHttpError extends Error {constructor(readonly status: number){super('preview unavailable');}}

function decode(value: string | null,limit: number): string | null {
  if (!value) return null;
  const entities: Record<string,string> = {amp:'&',lt:'<',gt:'>',quot:'"',apos:"'",nbsp:' '};
  const result = value.replace(/&(#x[0-9a-f]+|#\d+|amp|lt|gt|quot|apos|nbsp);/gi,(whole,name: string) => {
    if (name[0] !== '#') return entities[name.toLowerCase()] || whole;
    const point = name[1].toLowerCase() === 'x' ? parseInt(name.slice(2),16) : parseInt(name.slice(1),10);
    return point > 0 && point <= 0x10ffff && !(point >= 0xd800 && point <= 0xdfff) ? String.fromCodePoint(point) : '';
  }).replace(/[\u0000-\u001f\u007f]/g,' ').replace(/\s+/g,' ').trim().slice(0,limit);
  return result || null;
}

export function metadata(html: string,base: string) {
  const tags = new Map<string,string>();
  // Bounded input and bounded individual tags prevent pathological regex work.
  for(const match of html.matchAll(/<meta\s[^>]{0,8192}>/gi)) {
    const attributes: Record<string,string> = {};
    for(const attr of match[0].matchAll(/([a-z_:][-a-z0-9_:.]*)\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))/gi))
      attributes[attr[1].toLowerCase()] = attr[2] ?? attr[3] ?? attr[4];
    const name = (attributes.property || attributes.name || '').toLowerCase();
    if (attributes.content && !tags.has(name)) tags.set(name,attributes.content);
  }
  const pick = (...keys: string[]) => keys.map(key=>tags.get(key)).find(Boolean) || null;
  const title = decode(pick('og:title','twitter:title') || html.match(/<title\b[^>]{0,1024}>([^<]{0,4096})<\/title>/i)?.[1] || null,200);
  const description = decode(pick('og:description','twitter:description','description'),300);
  let image: string | null = null;
  const raw = decode(pick('og:image:secure_url','og:image','twitter:image','twitter:image:src'),4096);
  if (raw) try { image = previewUrl(new URL(raw,base).href).href; } catch { /* text-only preview */ }
  return {title,description,image};
}

async function bodyUrl(req: Request): Promise<string> {
  const length = req.headers.get('Content-Length');
  if (length && (!/^\d+$/.test(length) || Number(length)>8192)) throw new Error('body');
  if (!req.body) throw new Error('body');
  const reader = req.body.getReader();const chunks: Uint8Array[] = [];let size=0;
  let timer: ReturnType<typeof setTimeout>;
  try {
    const read = async () => {
      for (;;) {
        const part=await reader.read();if(part.done)break;
        size+=part.value.byteLength;if(size>8192)throw new Error('body');chunks.push(part.value);
      }
      const bytes=new Uint8Array(size);let offset=0;for(const part of chunks){bytes.set(part,offset);offset+=part.byteLength;}
      const data=JSON.parse(new TextDecoder().decode(bytes));
      if(typeof data?.url!=='string')throw new Error('body');
      return data.url.trim();
    };
    return await Promise.race([read(),new Promise<never>((_,reject)=>{timer=setTimeout(()=>reject(new Error('body')),2000);})]);
  } finally {clearTimeout(timer!);await reader.cancel().catch(()=>{});reader.releaseLock();}
}

export function createLinkPreviewHandler(deps: Dependencies) {
  const now=deps.now || Date.now;
  const base=new URL(deps.base).origin;
  if(!base.startsWith('https://'))throw new Error('HTTPS backend required');
  const pending=new Map<string,Promise<PreviewRow>>();let imageRequests=0;
  type Raster={bytes:Uint8Array;mime:string;expires:number};
  const rasters=new Map<string,Raster>(),imagePending=new Map<string,Promise<Raster>>();let rasterBytes=0;
  const forgetRaster=(token:string)=>{const old=rasters.get(token);if(old)rasterBytes-=old.bytes.byteLength;rasters.delete(token);};
  const rememberRaster=(token:string,raster:Raster)=>{
    forgetRaster(token);
    while(rasters.size && (rasters.size>=24 || rasterBytes+raster.bytes.byteLength>12_000_000))forgetRaster(rasters.keys().next().value!);
    rasters.set(token,raster);rasterBytes+=raster.bytes.byteLength;
  };
  const imageUrl=(token: string)=>`${base}/functions/v1/link-preview?image=${token}`;
  const publicRow=(row: PreviewRow)=>({url:row.url,title:row.title,description:row.description,
    image_url:row.image_origin_url && ID.test(row.image_token) ? imageUrl(row.image_token) : null,
    domain:row.domain,fetched_at:row.fetched_at});
  return async (req: Request): Promise<Response> => {
    if(req.method==='OPTIONS')return new Response(null,{status:204,headers:PRIVATE});
    if(req.method==='GET') {
      const params=new URL(req.url).searchParams,token=(params.get('image') || '').toLowerCase();
      if(!ID.test(token)||params.getAll('image').length!==1||Array.from(params.keys()).some(key=>key!=='image'))return error(400);
      if(imageRequests>=12)return error(503);
      imageRequests++;
      try {
        let raster=rasters.get(token);
        if(raster && raster.expires<=now()){forgetRaster(token);raster=undefined;}
        if(!raster) {
          let work=imagePending.get(token);
          if(!work){
            work=(async()=>{
              const origin=await deps.image(token);if(!origin)throw new PreviewHttpError(404);
              if(!await deps.claimImage(token))throw new PreviewHttpError(429);
              const result=await deps.fetch(origin,'image',req.signal);
              const mime=rasterMime(result.bytes);if(!mime)throw new PreviewHttpError(422);
              const fresh={bytes:result.bytes,mime,expires:now()+300_000};rememberRaster(token,fresh);return fresh;
            })();
            imagePending.set(token,work);
            const current=work;void work.finally(()=>{if(imagePending.get(token)===current)imagePending.delete(token);}).catch(()=>{});
          }
          raster=await work;
        }else{rasters.delete(token);rasters.set(token,raster);}
        return new Response(new Uint8Array(raster.bytes),{headers:{...CORS,'Content-Type':raster.mime,'Content-Length':String(raster.bytes.byteLength),
          'Cache-Control':'public, max-age=3600','CDN-Cache-Control':'public, max-age=86400',
          'X-Content-Type-Options':'nosniff','Content-Security-Policy':"default-src 'none'; sandbox",'Cross-Origin-Resource-Policy':'cross-origin'}});
      } catch(failure) {return error(failure instanceof PreviewHttpError?failure.status:502);} finally {imageRequests--;}
    }
    if(req.method!=='POST')return error(405);
    const authorization=req.headers.get('Authorization') || '';
    if(!/^Bearer \S+$/i.test(authorization) || authorization.length>8192)return error(401);
    let user: Awaited<ReturnType<Dependencies['authenticate']>>;
    try {user=await deps.authenticate(authorization);} catch {return error(503);}
    if(!user || user.anonymous)return error(401);
    let raw: string,parsed: URL;
    try {raw=await bodyUrl(req);parsed=previewUrl(raw);} catch {return error(400);}
    let cached: PreviewRow | null=null;
    try {cached=await deps.read(raw);} catch { /* safe fetch can still provide a transient text preview */ }
    const verified=cached?.verified_at ? Date.parse(cached.verified_at) : NaN;
    if(cached?.url===raw && Number.isFinite(verified) && verified<=now()+60_000 && verified>now()-7*86400_000)
      return json(publicRow(cached));
    let work=pending.get(raw);
    if(!work) {
      if(pending.size>=12)return error(503);
      work=(async()=>{
        let allowed: boolean;
        try {allowed=await deps.claim(user.id);} catch {throw new PreviewHttpError(503);}
        if(!allowed)throw new PreviewHttpError(429);
        const result=await deps.fetch(parsed.href,'html',req.signal);
        const data=metadata(new TextDecoder().decode(result.bytes),result.url);
        const token=cached?.image_token && ID.test(cached.image_token)?cached.image_token:(deps.randomId || (()=>crypto.randomUUID()))();
        const row: PreviewRow={url:raw,title:data.title,description:data.description,
          image_url:data.image?imageUrl(token):null,image_origin_url:data.image,image_token:token,
          domain:plainHostname(parsed).replace(/^www\./,''),fetched_at:new Date(now()).toISOString(),verified_at:new Date(now()).toISOString()};
        try {return await deps.save(row);} catch {
          // A missing/unavailable cache never blocks publishing, and never
          // returns a thumbnail token which was not actually persisted.
          row.image_origin_url=null;row.image_url=null;
        }
        return row;
      })();
      pending.set(raw,work);
      const current=work;void work.finally(()=>{if(pending.get(raw)===current)pending.delete(raw);}).catch(()=>{});
    }
    try {return json(publicRow(await work));} catch(failure) {return error(failure instanceof PreviewHttpError?failure.status:502);}
  };
}

import { serveBusinessRequest } from '../_shared/serveBusinessRequest.ts';
import { createClient } from 'npm:@supabase/supabase-js@2.112.3';
import { createLinkPreviewHandler } from './handler.ts';
import { createSafeFetch } from './transport.ts';
import { createDenoPinnedRequest } from './denoTransport.ts';

const base=Deno.env.get('SUPABASE_URL')!;
const client=createClient(base,Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!,{
  auth:{persistSession:false,autoRefreshToken:false},
});
const fields='url,title,description,image_url,domain,fetched_at,verified_at,image_origin_url,image_token';
serveBusinessRequest(createLinkPreviewHandler({
  base,fetch:createSafeFetch({request:createDenoPinnedRequest()}),
  async authenticate(authorization) {
    const {data,error}=await client.auth.getUser(authorization.replace(/^Bearer\s+/i,''));
    return error || !data.user ? null : {id:data.user.id,anonymous:data.user.is_anonymous};
  },
  async read(url) {
    const {data,error}=await client.from('link_previews').select(fields).eq('url',url).maybeSingle();
    if(error)throw new Error('Preview cache unavailable');return data;
  },
  async save(row) {
    const {data,error}=await client.rpc('store_verified_link_preview',{
      p_url:row.url,p_title:row.title,p_description:row.description,
      p_image_origin_url:row.image_origin_url,p_domain:row.domain,p_backend_origin:new URL(base).origin,
    });
    if(error || !data)throw new Error('Preview cache unavailable');return data;
  },
  async claim(actor) {
    const {data,error}=await client.rpc('claim_link_preview_fetch',{p_actor:actor});
    if(error)throw new Error('Preview budget unavailable');return data===true;
  },
  async image(token) {
    const {data,error}=await client.from('link_previews').select('image_origin_url').eq('image_token',token).not('verified_at','is',null).maybeSingle();
    if(error)throw new Error('Preview cache unavailable');return data?.image_origin_url || null;
  },
  async claimImage(token) {
    const {data,error}=await client.rpc('claim_link_preview_image',{p_token:token});
    if(error)throw new Error('Preview budget unavailable');return data===true;
  },
}), request => request.method === 'POST');

// A conservative public-Internet policy. Source: IANA IPv4/IPv6 special-purpose
// registries. Some unusual public anycast ranges are intentionally excluded;
// a missing preview must never become access to an internal service.
import { isIP } from 'node:net';

export class PreviewError extends Error {
  constructor(public readonly code: 'blocked' | 'timeout' | 'upstream' | 'too_large') {
    super(code); this.name = 'PreviewError';
  }
}

export function isPublicAddress(address: string): boolean {
  if (address.includes('%')) return false;
  const family = isIP(address);
  if (family === 4) {
    const [a,b,c] = address.split('.').map(Number);
    return !(a === 0 || a === 10 || a === 127 || a >= 224
      || (a === 100 && b >= 64 && b <= 127)
      || (a === 169 && b === 254) || (a === 172 && b >= 16 && b <= 31)
      || (a === 192 && (b === 168 || (b === 0 && c === 0) || (b === 0 && c === 2) || (b === 88 && c === 99)))
      || (a === 198 && (b === 18 || b === 19 || (b === 51 && c === 100)))
      || (a === 203 && b === 0 && c === 113));
  }
  if (family !== 6 || address.includes('.')) return false;
  const first = parseInt(address.split(':')[0] || '0',16);
  const second = parseInt(address.split(':')[1] || '0',16);
  // Only global unicast, excluding special protocol assignments, documentation,
  // and 6to4. IPv4-mapped/NAT64/ULA/link-local/loopback never enter this range.
  return first >= 0x2000 && first <= 0x3fff
    && !(first === 0x2001 && (second <= 0x01ff || second === 0x0db8))
    && first !== 0x2002 && first !== 0x3fff;
}

export function plainHostname(url: URL): string {
  return url.hostname.replace(/^\[|\]$/g,'').toLowerCase();
}

export function previewUrl(raw: string): URL {
  if (typeof raw !== 'string' || raw.length > 4096 || /[\u0000-\u0020\u007f]/.test(raw)) throw new PreviewError('blocked');
  let url: URL;
  try { url = new URL(raw); } catch { throw new PreviewError('blocked'); }
  if (!['http:','https:'].includes(url.protocol) || url.username || url.password || url.port) throw new PreviewError('blocked');
  if (url.hostname.endsWith('.')) url.hostname = url.hostname.slice(0,-1);
  const host = plainHostname(url);
  if (isIP(host)) {
    if (!isPublicAddress(host)) throw new PreviewError('blocked');
  } else {
    if (host.length > 253 || !host.includes('.') || /\.(?:localhost|local|internal|lan|home|onion|invalid|test|example)$/.test(host)
      || host.split('.').some(part => !/^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/.test(part))) throw new PreviewError('blocked');
  }
  url.hash = '';
  return url;
}

export type Address = { address: string; family: number };
export function choosePublicAddress(records: Address[]): Address {
  if (!records.length || records.length > 32 || records.some(row => !isPublicAddress(row.address) || isIP(row.address) !== row.family)) throw new PreviewError('blocked');
  // A validated literal is passed into the socket call. Never resolve the
  // original hostname a second time between inspection and connection.
  return records.find(row => row.family === 4) || records[0];
}

import { lookup } from 'node:dns/promises';
import { request as httpRequest, type IncomingMessage, type RequestOptions } from 'node:http';
import { request as httpsRequest, type RequestOptions as HttpsOptions } from 'node:https';
import { checkServerIdentity } from 'node:tls';
import { isIP } from 'node:net';
import { Buffer } from 'node:buffer';
import { choosePublicAddress, plainHostname, previewUrl, PreviewError, type Address } from './networkPolicy.ts';

export type FetchKind = 'html' | 'image';
export type PinnedResult = { status: number; headers: Record<string,string>; bytes: Uint8Array };
export type SafeResult = PinnedResult & { url: string };
type PinnedRequest = (url: URL, address: Address, kind: FetchKind, signal: AbortSignal) => Promise<PinnedResult>;
const MAX_BYTES = { html: 300_000, image: 2_000_000 };

export function pinnedOptions(url: URL, address: Address, signal: AbortSignal): HttpsOptions {
  const host = plainHostname(url);
  return {
    protocol: url.protocol,
    hostname: address.address,
    family: address.family,
    port: url.protocol === 'https:' ? 443 : 80,
    path: url.pathname + url.search,
    method: 'GET', agent: false, signal, maxHeaderSize: 16_384,
    servername: isIP(host) ? undefined : host,
    rejectUnauthorized: true,
    checkServerIdentity: (_name, certificate) => checkServerIdentity(host,certificate),
    headers: {
      Host: url.host, Accept: 'text/html,application/xhtml+xml,image/avif,image/webp,image/png,image/jpeg,image/gif;q=0.8',
      'Accept-Encoding': 'identity', Connection: 'close',
      'User-Agent': 'PlatinumCirclesPreview/2.0 (+https://platinumcircles.app)',
    },
  };
}

// The Node implementation supports real stream fixtures. The hosted entrypoint
// injects the native Deno transport because its older node:https shim ignores SNI.
export function createPinnedRequest(requests = { http: httpRequest, https: httpsRequest }): PinnedRequest {
  return (url,address,kind,signal) => new Promise((resolve,reject) => {
    if (signal.aborted) { reject(new PreviewError('timeout')); return; }
    let settled = false, response: IncomingMessage | undefined;
    const chunks: Uint8Array[] = []; let size = 0;
    const headers: Record<string,string> = {};
    const done = (error?: Error) => {
      if (settled) return;
      settled = true; signal.removeEventListener('abort',abort);
      if (error) reject(error);
      else resolve({ status: response!.statusCode || 0, headers, bytes: Buffer.concat(chunks,size) });
      response?.destroy(); request.destroy();
    };
    const abort = () => done(new PreviewError('timeout'));
    const send = url.protocol === 'https:' ? requests.https : requests.http;
    const request = send(pinnedOptions(url,address,signal) as RequestOptions, res => {
      response = res;
      for (const key of ['location','content-type','content-encoding']) {
        const value = res.headers[key];
        if (Array.isArray(value)) { done(new PreviewError('upstream')); return; }
        if (value) headers[key] = value;
      }
      if ([301,302,303,307,308].includes(res.statusCode || 0)) { done(); return; }
      if (res.statusCode !== 200 || (headers['content-encoding'] && headers['content-encoding'].toLowerCase() !== 'identity')) { done(new PreviewError('upstream')); return; }
      const mime = (headers['content-type'] || '').split(';')[0].trim().toLowerCase();
      if (kind === 'html' ? !['text/html','application/xhtml+xml'].includes(mime) : !['image/jpeg','image/png','image/gif','image/webp','image/avif'].includes(mime)) { done(new PreviewError('upstream')); return; }
      res.on('data',(chunk: Buffer) => {
        if (settled) return;
        const remaining = MAX_BYTES[kind] - size;
        if (kind === 'image' && chunk.byteLength > remaining) { done(new PreviewError('too_large')); return; }
        const part = chunk.subarray(0,remaining);chunks.push(part);size += part.byteLength;
        if (kind === 'html' && size >= MAX_BYTES.html) done();
      });
      res.once('end',() => done());
      res.once('aborted',() => done(new PreviewError('upstream')));
      res.once('error',() => done(new PreviewError('upstream')));
    });
    request.once('error',() => done(new PreviewError(signal.aborted ? 'timeout' : 'upstream')));
    signal.addEventListener('abort',abort,{once:true});
    if (signal.aborted) abort();
    else request.end();
  });
}

async function withinDeadline<T>(promise: Promise<T>,signal: AbortSignal): Promise<T> {
  if (signal.aborted) throw new PreviewError('timeout');
  let abort: () => void = () => {};
  try {
    return await Promise.race([promise,new Promise<T>((_,reject) => {
      abort = () => reject(new PreviewError('timeout'));
      signal.addEventListener('abort',abort,{once:true});
    })]);
  } finally { signal.removeEventListener('abort',abort); }
}

export function createSafeFetch(deps: {
  resolve?: (host: string) => Promise<Address[]>;
  request?: PinnedRequest;
  timeoutMs?: number;
} = {}) {
  const resolve = deps.resolve || (host => lookup(host,{all:true,verbatim:true}));
  const request = deps.request || createPinnedRequest();
  return async (raw: string,kind: FetchKind,callerSignal?: AbortSignal): Promise<SafeResult> => {
    const controller = new AbortController();
    const abort = () => controller.abort();
    callerSignal?.addEventListener('abort',abort,{once:true});
    if (callerSignal?.aborted) abort();
    const timer = setTimeout(abort,deps.timeoutMs ?? 8_000);
    try {
      let url = previewUrl(raw);
      const seen = new Set<string>();
      for(let redirects = 0; redirects <= 4; redirects++) {
        if (seen.has(url.href)) throw new PreviewError('upstream');
        seen.add(url.href);
        const host = plainHostname(url);
        const records = isIP(host) ? [{address:host,family:isIP(host)}] : await withinDeadline(resolve(host),controller.signal);
        const address = choosePublicAddress(records);
        const result = await withinDeadline(request(url,address,kind,controller.signal),controller.signal);
        if (![301,302,303,307,308].includes(result.status)) return {...result,url:url.href};
        const location = result.headers.location;
        if (!location || redirects === 4) throw new PreviewError('upstream');
        let next: URL;
        try { next = previewUrl(new URL(location,url).href); } catch { throw new PreviewError('blocked'); }
        if (url.protocol === 'https:' && next.protocol !== 'https:') throw new PreviewError('blocked');
        url = next;
      }
      throw new PreviewError('upstream');
    } finally { clearTimeout(timer);callerSignal?.removeEventListener('abort',abort); }
  };
}

export function rasterMime(bytes: Uint8Array): string | null {
  if (bytes.length < 12) return null;
  if (bytes[0]===0xff && bytes[1]===0xd8 && bytes[2]===0xff) return 'image/jpeg';
  if ([137,80,78,71,13,10,26,10].every((n,i)=>bytes[i]===n)) return 'image/png';
  const ascii=(start:number,end:number)=>String.fromCharCode(...bytes.subarray(start,end));
  if (['GIF87a','GIF89a'].includes(ascii(0,6))) return 'image/gif';
  if (ascii(0,4)==='RIFF' && ascii(8,12)==='WEBP') return 'image/webp';
  if (ascii(4,8)==='ftyp' && ['avif','avis'].includes(ascii(8,12))) return 'image/avif';
  return null;
}
